#include "policy.hpp"
#include <cassert>
#include <iostream>
int main(){HumanPolicy p{0,-1,{900,600,80,100},{900,600,80,100},1000,1000,{9,9,9},{100,100,100},0,0};Observable x{899,0,999,80,false,false,false,false,false};assert(!beginvisit(p,x));x.shells=900;assert(beginvisit(p,x));assert(choosehuman(p,x,true)==21);x.shells=600;assert(choosehuman(p,x,true)==0);x.shells=650;x.chance=90;assert(choosehuman(p,x,false)==0);assert(choosehuman(p,x,true)==1);p.startchance=20;x.shells=999;x.chance=19;assert(!beginvisit(p,x));x.chance=20;assert(beginvisit(p,x));x.full=true;x.shells=0;x.chance=6;int a=choosehuman(p,x,true);assert((a-101)%3+1==3&&(a-101)/3==45);x.rupees=900;a=choosehuman(p,x,true);assert(a==103);x.ntsc=true;x.rupees=800;a=choosehuman(p,x,true);assert(a==104);p.restock=1;a=choosehuman(p,x,true);assert((a-101)%4+1==4);x.chance=80;x.shells=0;a=choosehuman(p,x,true);assert((a-101)%4+1==1);p.partial=1;x.shells=10;x.chance=6;assert(choosehuman(p,x,true)==10);p.partial=0;p.band1=100;p.threshold={10,10,10};p.target={-30,60,100};x.shells=100;assert(choosehuman(p,x,true)==30);x.shells=101;assert(choosehuman(p,x,true)==55);auto d=inputcounts();assert(d[100][20]==3&&d[20][20]==2);cout<<"Observable rule boundaries, session activation, intermediate wagers, partial wagers, funded purchases, regional limits, and shortest paths passed.\n";}
